            "اليسع عليه السلام", "إلياس عليه السلام", "يونس عليه السلام", "شعيب عليه السلام", 1,
            "قال تعالى في سورة الصافات: ﴿وَإِنَّ إِلْيَاسَ لَمِنَ الْمُرْسَلِينَ * إِذْ قَالَ لِقَوْمِهِ أَلَا تَتَّقُونَ * أَتَدْعُونَ بَعْلًا وَتَذَرُونَ أَحْسَنَ الْخَالِقِينَ﴾."),
        q(226L, PROPHETS, HARD, "كم عدد أخوة نبي الله يوسف عليه السلام؟",
            "سبعة إخوة", "عشرة إخوة (مع بنيامين يصبحون أحد عشر أخاً له)", "اثنا عشر أخاً", "خمسة إخوة", 1,
            "كان ليعقوب اثنا عشر ولداً هم الأسباط، فيوسف عليه السلام له أحد عشر أخاً رأى كواكبهم تسجد له في المنام."),
        q(227L, PROPHETS, HARD, "ما اسم الجبل الذي استوت عليه سفينة نوح عليه السلام بعد الطوفان؟",
            "جبل الطور", "جبل الجودي", "جبل أحد", "جبل أرارات في القرآن", 1,
            "قال تعالى: ﴿وَاسْتَوَتْ عَلَى الْجُودِيِّ ۖ وَقِيلَ بُعْدًا لِّلْقَوْمِ الظَّالِمِينَ﴾."),
        q(228L, PROPHETS, HARD, "ما اسم الفتى الذي رافق موسى عليه السلام في رحلته إلى مجمع البحرين للقاء الخضر؟",
            "هارون", "يوشع بن نون", "قارون", "طالوت", 1,
            "ثبت في الصحيح أن فتى موسى عليه السلام في سورة الكهف هو يوشع بن نون الذي نبأه الله بعد موسى."),
        q(229L, PROPHETS, HARD, "من النبي الذي ذُكر في سورة مريم أنه كان «يَأْمُرُ أَهْلَهُ بِالصَّلَاةِ وَالزَّكَاةِ وَكَانَ عِندَ رَبِّهِ مَرْضِيًّا»؟",
            "إسحاق عليه السلام", "إسماعيل عليه السلام", "يعقوب عليه السلام", "داود عليه السلام", 1,
            "أثنى الله على نبيه إسماعيل عليه السلام بصدق الوعد والأمر بالصلاة والزكاة."),
        q(230L, PROPHETS, HARD, "كم عاماً تاه بنو إسرائيل في الصحراء عقوبةً لهم على رفضهم دخول الأرض المقدسة مع موسى؟",
            "سبع سنين", "عشرون سنة", "أربعون سنة", "سبعون سنة", 2,
            "قال تعالى: ﴿قَالَ فَإِنَّهَا مُحَرَّمَةٌ عَلَيْهِمْ ۛ أَرْبَعِينَ سَنَةً ۛ يَتِيهُونَ فِي الْأَرْضِ﴾."),
        q(231L, PROPHETS, HARD, "من النبي الذي ضرب الله به المثل في سورة الصافات أنه «وَجَدْنَاهُ صَابِرًا ۚ نِّعْمَ الْعَبْدُ ۖ إِنَّهُ أَوَّابٌ»؟",
            "داود عليه السلام", "أيوب عليه السلام", "سليمان عليه السلام", "يوسف عليه السلام", 1,
            "أثنى الله على أيوب عليه السلام بهذه الشهادة العظيمة لصبره على البلاء، وكذلك أثنى على داود وسليمان بلفظ «نعم العبد إنه أواب»."),
        q(232L, PROPHETS, HARD, "من هو النبي الذي حبس الله له الشمس عن الغروب يوم فتح بيت المقدس حتى أتم الفتح؟",
            "داود عليه السلام", "يوشع بن نون عليه السلام", "موسى عليه السلام", "زكريا عليه السلام", 1,
            "في الحديث الصحيح أن الشمس لم تُحبس لبشر إلا ليوشع ليالي سار إلى بيت المقدس."),
        q(233L, PROPHETS, HARD, "ما اسم ملكة سبأ في الروايات التاريخية التي أسلمت مع سليمان لله رب العالمين؟",
            "آسية", "بلقيس", "هاجر", "سارة", 1,
            "عرفت ببلقيس ملكة سبأ، ولما رأت صرح سليمان وعظيم ملكه قالت: ﴿رَبِّ إِنِّي ظَلَمْتُ نَفْسِي وَأَسْلَمْتُ مَعَ سُلَيْمَانَ لِلَّهِ رَبِّ الْعَالَمِينَ﴾."),
        q(234L, PROPHETS, HARD, "ما اسم الصنم الذي صنعه السامري لبني إسرائيل في غياب موسى عليه السلام؟",
            "البعل", "العجل الذهبي", "اللات", "هبل", 1,
            "أخرج السامري لبني إسرائيل من حليهم عجلاً جسداً له خوار فافتتنوا به في غياب موسى لميقات ربه."),
        q(235L, PROPHETS, HARD, "في أي سورة ورد الحوار الشهير بين إبراهيم عليه السلام والنمرود الذي حاجّه في ربه؟",
            "سورة الأنبياء", "سورة البقرة", "سورة الشعراء", "سورة هود", 1,
            "ورد في سورة البقرة (الآية 258): ﴿فَإِنَّ اللَّهَ يَأْتِي بِالشَّمْسِ مِنَ الْمَشْرِقِ فَأْتِ بِهَا مِنَ الْمَغْرِبِ فَبُهِتَ الَّذِي كَفَرَ﴾."),
        q(236L, PROPHETS, HARD, "من النبي الذي أُمِر أن يركض برجله فينبع له مغتسل بارد وشراب شافٍ؟",
            "إسماعيل عليه السلام", "أيوب عليه السلام", "يونس عليه السلام", "موسى عليه السلام", 1,
            "قال تعالى لأيوب عليه السلام: ﴿ارْكُضْ بِرِجْلِكَ ۖ هَٰذَا مُغْتَسَلٌ بَارِدٌ وَشَرَابٌ﴾ فبرئ بإذن الله."),
        q(237L, PROPHETS, EASY, "ما اسم البئر المباركة التي فجّرها الله تحت قدمي إسماعيل وأمه هاجر في مكة؟",
            "بئر أريس", "بئر زمزم", "بئر رومة", "بئر بضاعة", 1,
            "نبع ماء زمزم المبارك في مكة إكراماً لهاجر وابنها إسماعيل عليهما السلام، وهو لما شُرب له."),
        q(238L, PROPHETS, EASY, "من النبي الذي اختاره الله ليكون «خاتم الأنبياء والمرسلين»؟",
            "عيسى عليه السلام", "محمد ﷺ", "إبراهيم عليه السلام", "موسى عليه السلام", 1,
            "قال تعالى: ﴿مَّا كَانَ مُحَمَّدٌ أَبَا أَحَدٍ مِّن رِّجَالِكُمْ وَلَٰكِن رَّسُولَ اللَّهِ وَخَاتَمَ النَّبِيِّينَ﴾."),
        q(239L, PROPHETS, MEDIUM, "كيف رأى إبراهيم عليه السلام في المنام أن يذبح ابنه إسماعيل ثم فداه الله؟",
            "فداه بناقة", "فداه بذبح عظيم (كبش من السماء)", "فداه بغزال", "فداه بذهب", 1,
            "لما أسلما للرؤيا الحق ناداه الله: ﴿وَنَادَيْنَاهُ أَن يَا إِبْرَاهِيمُ * قَدْ صَدَّقْتَ الرُّؤْيَا﴾ وفداه بذبح عظيم."),
        q(240L, PROPHETS, MEDIUM, "ما اسم الغلامين الصالحين اللذين حُفظ لهما كنزهما تحت الجدار لصلاح أبيهما في قصة موسى والخضر؟",
            "قابيل وهابيل", "غلامان يتيمان في المدينة", "ابنا شعيب", "ابنا هارون", 1,
            "أقام الخضر الجدار المائل لحفظ كنز يتيمين؛ لأن أباهما كان صالحاً، فأراد الله أن يبلغا أشدهما ويستخرجا كنزهما."),
        q(241L, PROPHETS, MEDIUM, "ما الحرفان أو الوصف الذي خصّ الله به نبي الله عيسى عليه السلام في سورة النساء إلى جانب كونه رسوله؟",
            "خليل الله", "كلمته ألقاها إلى مريم وروح منه", "كليم الله", "صفي الله", 1,
            "قال تعالى: ﴿إِنَّمَا الْمَسِيحُ عِيسَى ابْنُ مَرْيَمَ رَسُولُ اللَّهِ وَكَلِمَتُهُ أَلْقَاهَا إِلَىٰ مَرْيَمَ وَرُوحٌ مِّنْهُ﴾."),
        q(242L, PROPHETS, HARD, "في أي سورة ورد ذكر نبي الله «اليسع» عليه السلام مرتين إلى جانب إسماعيل وإلياس؟",
            "سورة الأنعام وسورة ص", "سورة البقرة وآل عمران", "سورة النحل والإسراء", "سورة الفرقان والشعراء", 0,
            "ذُكر اليسع عليه السلام مرتين في القرآن الكريم: في سورة الأنعام وسورة ص."),
        q(243L, PROPHETS, MEDIUM, "من الذي أرشد أم موسى عليه السلام لتُلقي رضيعها في اليمّ مطمئنةً بوعد الله؟",
            "خادمة القصر", "وحيٌ وإلهام من الله تعالى لها", "نبوءة كاهن", "رسالة من هارون", 1,
            "قال تعالى: ﴿وَأَوْحَيْنَا إِلَىٰ أُمِّ مُوسَىٰ أَنْ أَرْضِعِيهِ ۖ فَإِذَا خِفْتِ عَلَيْهِ فَأَلْقِيهِ فِي الْيَمِّ﴾."),
        q(244L, PROPHETS, EASY, "من النبي الذي أُمِر ببناء المسجد الحرام أو رفع قواعده في مكة؟",
            "موسى وهارون", "إبراهيم وإسماعيل عليهما السلام", "داود وسليمان", "نوح وإدريس", 1,
            "قال تعالى: ﴿وَإِذْ يَرْفَعُ إِبْرَاهِيمُ الْقَوَاعِدَ مِنَ الْبَيْتِ وَإِسْمَاعِيلُ﴾."),
        q(245L, PROPHETS, MEDIUM, "ماذا فعل نبي الله إبراهيم عليه السلام بأصنام قومه ليقيم عليهم الحجة؟",
            "حطمها جميعاً إلا كبيرهم ليُسألوا", "أحرقها في البحر", "أخفاها في الغار", "تركها كما هي", 0,
            "جعلها جذاذاً إلا كبيراً لهم لعلهم إليه يرجعون ويدركوا عجز الأصنام عن الدفاع عن نفسها."),
        q(246L, PROPHETS, HARD, "ما اسم النبي الذي عُرف في الحديث أن الله أهلك قوماً بعده، وأن الله أيده بنبتة اليقطين حين أُلقي على الساحل؟",
            "إلياس عليه السلام", "يونس عليه السلام", "أيوب عليه السلام", "لوط عليه السلام", 1,
            "أنبت الله على يونس عليه السلام شجرة من يقطين تظلله وتطعمه وهو سقيم على الساحل بعد خروجه من بطن الحوت."),
        q(247L, PROPHETS, MEDIUM, "ما الحرفة التي اشتغل بها نبي الله داود عليه السلام ليأكل من عمل يده؟",
            "النجارة", "صناعة الدروع الحديدية", "الصيد", "الحياكة", 1,
            "علمه الله صنعة لبوس (الدروع) لتحصنهم من بأسهم، وكان لا يأكل إلا من عمل يده."),
        q(248L, PROPHETS, EASY, "من النبي الذي كان يفسر الرؤى والأحلام في السجن وللملك في مصر؟",
            "يونس عليه السلام", "يوسف عليه السلام", "موسى عليه السلام", "زكريا عليه السلام", 1,
            "آتى الله يوسف عليه السلام علم تأويل الأحاديث، فأوّل رؤيا صاحبي السجن ثم رؤيا ملك مصر في السبع البقرات السمان."),
        q(425L, PROPHETS, EASY, "من النبي الذي أُرسل إلى قوم ثمود الذين كانوا ينحتون من الجبال بيوتاً آمنين؟",
            "هود عليه السلام", "صالح عليه السلام", "لوط عليه السلام", "شعيب عليه السلام", 1,
            "دعا صالح عليه السلام قوم ثمود إلى عبادة الله وحده وأراهم آية الناقة، فلما عتوا عن أمر ربهم أخذتهم الرجفة."),
        q(426L, PROPHETS, EASY, "ما اسم أم البشرية وزوجة نبي الله آدم عليه السلام؟",
            "سارة", "حواء", "هاجر", "مريم", 1,
            "خلق الله حواء من ضلع آدم عليه السلام ليسكن إليها، وأهبطهما الله إلى الأرض لعمارتها وعبادته."),
        q(427L, PROPHETS, EASY, "ما اسما ابني آدم عليه السلام اللذين قرّبا قرباناً فتُقُبّل من أحدهما ولم يُتقبّل من الآخر؟",
            "يوسف وبنيامين", "هابيل وقابيل", "إسماعيل وإسحاق", "الحسن والحسين", 1,
            "تقبل الله قربان هابيل لتقواه: ﴿إِنَّمَا يَتَقَبَّلُ اللَّهُ مِنَ الْمُتَّقِينَ﴾، فحسده قابيل وقتله ظلماً."),
        q(428L, PROPHETS, EASY, "من النبي الذي يُعرف بلقب «المسيح ابن مريم» ورُفع إلى السماء حياً؟",
            "يحيى عليه السلام", "عيسى عليه السلام", "زكريا عليه السلام", "هارون عليه السلام", 1,
            "عيسى ابن مريم عليه السلام رفعه الله إليه وسينزل قبل يوم القيامة حكماً مقسطاً."),
        q(429L, PROPHETS, EASY, "من النبي الذي دعا ربه بقوله: ﴿رَبِّ اجْعَلْنِي مُقِيمَ الصَّلَاةِ وَمِن ذُرِّيَّتِي﴾؟",
            "نوح عليه السلام", "إبراهيم عليه السلام", "موسى عليه السلام", "يعقوب عليه السلام", 1,
            "دعا الخليل إبراهيم عليه السلام بهذه الدعوات المباركات في سورة إبراهيم لاهتمامه بالصلاة والذرية الصالحة."),
        q(430L, PROPHETS, EASY, "من النبي الذي قال لابنه يا بني اركب معنا ولا تكن مع الكافرين فأبى الابن؟",
            "إبراهيم عليه السلام", "نوح عليه السلام", "لوط عليه السلام", "يعقوب عليه السلام", 1,
            "رفض ابن نوح أن يركب السفينة قائلاً سآوي إلى جبل يعصمني من الماء، فكان من المغرقين."),
        q(431L, PROPHETS, EASY, "من النبي الذي استُخلف في رعاية ابنه بعد أن رأى في نومه أحد عشر كوكباً والشمس والقمر له ساجدين؟",
            "إسحاق عليه السلام", "يوسف بن يعقوب عليه السلام", "إسماعيل عليه السلام", "بنيامين", 1,
            "قصّ يوسف عليه السلام رؤياه على أبيه يعقوب فنصحه ألا يقصصها على إخوته لئلا يكيدوا له كيداً."),
        q(432L, PROPHETS, EASY, "ما اسم العدو الطاغية الذي ادعى الألوهية وأغرقه الله في البحر وهو يطارد موسى وبني إسرائيل؟",
            "النمرود", "فرعون", "جالوت", "قارون", 1,
            "نجّى الله بدن فرعون بعد غرقه في اليم ليكون لمن خلفه آية وعبرة."),
        q(433L, PROPHETS, EASY, "ما اسم النبي الذي قَبِل ألا يرفع يده على أخيه لو بسط له يده بالقتل؟",
            "هابيل بن آدم (المؤمن الصالح)", "نوح عليه السلام", "يوسف عليه السلام", "داود عليه السلام", 0,
            "قال هابيل لأخيه قابيل: ﴿لَئِن بَسَطتَ إِلَيَّ يَدَكَ لِتَقْتُلَنِي مَا أَنَا بِبَاسِطٍ يَدِيَ إِلَيْكَ لِأَقْتُلَكَ ۖ إِنِّي أَخَافُ اللَّهَ رَبَّ الْعَالَمِينَ﴾."),
        q(434L, PROPHETS, MEDIUM, "ما الحجة الفاصلة التي أخرس بها إبراهيم عليه السلام الملك الجبار النمرود؟",
            "أخبره عن يوم القيامة", "قال له: إن الله يأتي بالشمس من المشرق فأت بها من المغرب", "ألقى عصاه فتحولت ثعباناً", "أراه الناقة", 1,
            "بهت النمرود وعجز عن الجواب عندما تحداه إبراهيم بتغيير مجرى الشمس."),
        q(435L, PROPHETS, MEDIUM, "بماذا اتفق الشيخ الكبير في مدين مع موسى عليه السلام ليزوجه إحدى ابنتيه؟",
            "أن يأجره ثماني حجج وإن أتم عشراً فمن عنده في رعي الغنم", "أن يبني له قصراً في مصر", "أن يعلمه السحر", "أن يسافر معه إلى الشام", 0,
            "التقى موسى عليه السلام بابنتي الشيخ الكبير في مدين وسقى لهما، فقالت إحداهما: ﴿يَا أَبَتِ اسْتَأْجِرْهُ ۖ إِنَّ خَيْرَ مَنِ اسْتَأْجَرْتَ الْقَوِيُّ الْأَمِينُ﴾."),
        q(436L, PROPHETS, MEDIUM, "ما الفعل الذي أمر الله نبيه موسى عليه السلام به أمام جبل الطور حين أراد الله تكليمه وذكره بالوادي المقدس؟",
            "أن يرفع يديه فقط", "أن يخلع نعليه؛ لأنه بالوادي المقدس طوى", "أن يسجد على صخرة", "أن يقرأ التوراة", 1,
            "قال تعالى لموسى عليه السلام: ﴿فَاخْلَعْ نَعْلَيْكَ ۖ إِنَّكَ بِالْوَادِ الْمُقَدَّسِ طُوًى﴾."),
        q(437L, PROPHETS, MEDIUM, "ماذا طلب موسى عليه السلام من ربه في الميقات فردّ الله عليه بأنه لن يراه في الدنيا وتجلى للجبل فجعله دكاً؟",
            "أن يُرِيه الملائكة", "قال: ﴿رَبِّ أَرِنِي أَنظُرْ إِلَيْكَ﴾", "أن ينصره في البحر", "أن ينزل المائدة", 1,
            "خرّ موسى صعقاً لما تجلى الله للجبل في سورة الأعراف، فلما أفاق سبّح الله وتاب إليه."),
        q(438L, PROPHETS, MEDIUM, "من النبي الذي أُمِر أن يبني سفينةً في أرض جافة فكان قومه يسخرون منه كلما مروا عليه؟",
            "هود عليه السلام", "نوح عليه السلام", "إبراهيم عليه السلام", "لوط عليه السلام", 1,
            "قال لهم نوح عليه السلام: ﴿إِن تَسْخَرُوا مِنَّا فَإِنَّا نَسْخَرُ مِنكُمْ كَمَا تَسْخَرُونَ﴾."),
        q(439L, PROPHETS, MEDIUM, "ما الآيتان العظيمتان اللتان أراهما الله لموسى عليه السلام قبل دخوله على فرعون أول مرة؟",
            "انفلاق البحر والمن والسلوى", "انقلاب العصا حيةً تسعى وخروج اليد بيضاء من غير سوء", "انشقاق القمر والناقة", "تسبيح الجبال والطير", 1,
            "أيد الله موسى عليه السلام بآية العصا التي تبتلع حبال السحرة وبآية اليد البيضاء المضيئة."),
        q(440L, PROPHETS, MEDIUM, "ماذا كان مصير سحرة فرعون بعدما رأوا عصا موسى تلتقف ما يأفكون؟",
            "هربوا خارج مصر", "ألقوا سجداً وقالوا آمنا برب العالمين، وثبتوا رغم تهديد فرعون", "انضموا إلى جنود فرعون", "نقموا على موسى", 1,
            "أدرك السحرة بخبرتهم أن ما جاء به موسى معجزة إلهية لا سحر، فآمنوا وصلب إيمانهم أمام تهديد فرعون."),
        q(441L, PROPHETS, MEDIUM, "بماذا أهلك الله قوم لوط عليه السلام حين عتوا عن أمر ربهم وأصروا على الفاحشة؟",
            "بالطوفان", "بجعل عالي قراهم سافلها وأمطر عليهم حجارة من سجيل منضود", "بصيحة واحدة فقط", "بريح صرصر عاتية", 1,
            "أخرج الله لوطاً وأهله ليلاً إلا امرأته، ثم قلب قراهم وأمطر عليهم حجارة من سجيل."),
        q(442L, PROPHETS, MEDIUM, "ما العذاب الذي أهلك الله به قوم عاد الذين استكبروا في الأرض وقالوا من أشد منا قوة؟",
            "الطوفان", "ريح صرصر عاتية سخّرها الله عليهم سبع ليالٍ وثمانية أيام حسوماً", "الغرق في البحر", "الخسف في الأرض", 1,
            "دمرت الريح العقيم ديار عاد فصاروا كأعجاز نخل خاوية ونجّى الله هوداً والذين آمنوا معه."),
        q(443L, PROPHETS, MEDIUM, "ماذا فعل إخوة يوسف عليه السلام عندما عادوا إلى أبيهم بعد إلقائه في الجُب ليصدقهم؟",
            "أخبروه أنه سافر إلى مصر", "جاءوا على قميصه بدم كذب وزعموا أن الذئب أكله", "قالوا إنه ضاع في الجبل", "أخفوا أمر غيابه", 1,
            "لم يصدقهم يعقوب عليه السلام، فلحظ أن القميص سليم لم يمزقه الذئب وقال: ﴿بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا ۖ فَصَبْرٌ جَمِيلٌ﴾."),
        q(444L, PROPHETS, MEDIUM, "من الشخص الذي أشار على فرعون أو الملك بأن يبحث في رؤيا السبع البقرات السمان وتأويل يوسف لها؟",
            "العزيز نفسه", "الساقي الذي نجا من السجن وتذكر يوسف بعد أمة (بضع سنين)", "صاحب الخبز", "هامان", 1,
            "تذكر الساقي أمانة يوسف وعلمه في تعبير الرؤيا بعد سنين، فاستأذن الملك في سؤاله بالسجن."),
        q(445L, PROPHETS, MEDIUM, "كيف تخلص النبي سليمان عليه السلام من فتنة فتّنته عندما راجع استغفاره أو بماذا دعا الله أن يغفر له ويهبه؟",
            "دعا بقوله: ﴿رَبِّ اغْفِرْ لِي وَهَبْ لِي مُلْكًا لَّا يَنبَغِي لِأَحَدٍ مِّن بَعْدِي﴾", "ترك الحكم للجن", "طلب أن يموت", "هاجر إلى الشام", 0,
            "فزع سليمان عليه السلام بالتوبة والاستغفار ودعا الله أن يهبه ملكاً فريداً فألان له الريح والشياطين."),
        q(446L, PROPHETS, MEDIUM, "ما القصة التي وردت في سورة «ص» واختصم فيها خصمان تسورا المحراب على نبي الله داود عليه السلام؟",
            "قصة التسع والتسعين نعجة والنعجة الواحدة", "قصة السفينة والبحر", "قصة الحرث والغنم", "قصة بناء المسجد", 0,
            "كانت فتنة وابتلاء لداود عليه السلام ليحكم بالعدل ولا يتبع الهوى، فاستغفر ربه وخر راكعاً وأناب."),
        q(447L, PROPHETS, MEDIUM, "من النبيان اللذان حكما في قضية الغنم التي نفشت (رعت ليلاً) في حرث قوم ففهمها الله الأصغر منهما؟",
            "موسى وهارون", "داود وابنه سليمان عليهما السلام", "إبراهيم وإسماعيل", "زكريا ويحيى", 1,
            "قال تعالى: ﴿فَفَهَّمْنَاهَا سُلَيْمَانَ ۚ وَكُلًّا آتَيْنَا حُكْمًا وَعِلْمًا﴾ حيث حكم باستغلال ألبان الغنم وصوفها ريثما يُصلح أصحابها الزرع."),
        q(448L, PROPHETS, MEDIUM, "ما الدعاء العظيم الذي دعا به نبي الله زكريا عليه السلام حين اشتعل الرأس شيباً ولم يكن يائساً من رحمة الله؟",
            "رب إني ظلمت نفسي", "﴿رَبِّ لَا تَذَرْنِي فَرْدًا وَأَنتَ خَيْرُ الْوَارِثِينَ﴾، و﴿رَبِّ هَبْ لِي مِن لَّدُنكَ ذُرِّيَّةً طَيِّبَةً﴾", "رب أشرح لي صدري", "رب أنزلنا منزلاً مباركاً", 1,
            "دعا زكريا ربه نداءً خفياً بقلب منكسر واثق، فبشرته الملائكة بيحيى سيداً وحصوراً ونبياً من الصالحين."),
        q(449L, PROPHETS, MEDIUM, "ما الكلمة التي ألقاها موسى عليه السلام عند الشدة لما تراءى الجمعان وقال أصحابه إنا لمدركون؟",
            "لن نقدر عليهم", "﴿كَلَّا ۖ إِنَّ مَعِيَ رَبِّي سَيَهْدِينِ﴾", "اهربوا إلى الجبال", "استسلموا لفرعون", 1,
            "ضرب موسى عليه السلام قمة اليقين بالله في أشد لحظات الخطر، فشق الله له البحر في التو."),
        q(450L, PROPHETS, HARD, "من النبي الذي أُمِر ألا يلتفت هو وأهله أثناء الخروج ليلاً، وقد تخلفت امرأته فكانت من الغابرين؟",
            "نوح عليه السلام", "لوط عليه السلام", "صالح عليه السلام", "شعيب عليه السلام", 1,
            "أخبرت الملائكة لوطاً عليه السلام أن يسري بأهله بقطع من الليل ولا يلتفت منهم أحد إلا امرأته الخائنة لقومها."),
        q(451L, PROPHETS, HARD, "ما العلاقة الأسرية بين نبي الله إبراهيم عليه السلام ونبي الله لوط عليه السلام؟",
            "لوط أخو إبراهيم", "لوط ابن أخي إبراهيم (ابن هاران)", "لوط والد إبراهيم", "لوط ابن عم داود", 1,
            "لوط بن هاران هو ابن أخي إبراهيم عليه السلام، آمن به وهاجر معه من العراق إلى الشام."),
        q(452L, PROPHETS, HARD, "ما دور الرجل الذي جاء يسعى من أقصى المدينة لمقابلة موسى عليه السلام في سورة القصص؟",
            "مؤمن آل فرعون", "رجل صالح نصح موسى بالخروج حين ائتمر به الملأ ليقتلوه", "السامري", "الفتى يوشع", 1,
            "قال تعالى في سورة القصص: ﴿وَجَاءَ رَجُلٌ مِّنْ أَقْصَى الْمَدِينَةِ يَسْعَىٰ قَالَ يَا مُوسَىٰ إِنَّ الْمَلَأَ يَأْتَمِرُونَ بِكَ لِيَقْتُلُوكَ فَاخْرُجْ﴾."),
        q(453L, PROPHETS, HARD, "ماذا كان رد مؤمن آل فرعون عندما أراد فرعون قتل موسى عليه السلام بدعوى أنه يخاف أن يبدل دينكم؟",
            "أيد فرعون في قوله", "دافع عن موسى قائلاً: ﴿أَتَقْتُلُونَ رَجُلًا أَن يَقُولَ رَبِّيَ اللَّهُ﴾", "سكت ولم ينطق", "حارب بني إسرائيل", 1,
            "كتم مؤمن آل فرعون إيمانه ثم جهر بنصيحة بليغة مخلدة في سورة غافر فوقاه الله سيئات ما مكروا."),
        q(454L, PROPHETS, HARD, "في قصة إبراهيم عليه السلام، لماذا اعتذر عند استغفاره لأبيه بعد أن تبين له أنه عدو لله؟",
            "لأن الله نهاه بعد استبانة الكفر؛ فلم يبقَ موضع للموعدة التي وعدها إياه", "لأنه نسي", "لأنه لم يعرف أباه", "لأنه سافر بعيداً", 0,
            "قال تعالى: ﴿وَمَا كَانَ اسْتِغْفَارُ إِبْرَاهِيمَ لِأَبِيهِ إِلَّا عَن مَّوْعِدَةٍ وَعَدَهَا إِيَّاهُ فَلَمَّا تَبَيَّنَ لَهُ أَنَّهُ عَدُوٌّ لِّلَّهِ تَبَرَّأَ مِنْهُ﴾."),
        q(455L, PROPHETS, HARD, "من المقصودان بوصف «الذبيحين» في السيرة النبوية والأثر المشهور؟",
            "موسى وهارون", "إسماعيل عليه السلام وعبد الله والد النبي ﷺ", "يوسف وبنيامين", "إسحاق ويعقوب", 1,
            "روي أن النبي ﷺ قال: أنا ابن الذبيحين؛ يعني جده إسماعيل عليه السلام وأباه عبد الله حين نذر عبد المطلب ذبحه ثم فداه بمئة من الإبل."),
        q(456L, PROPHETS, HARD, "كم استمرت الريح الصرصر العاتية على قوم عاد كما نصّت عليه سورة الحاقة؟",
            "ثلاثة أيام", "سبع ليالٍ وثمانية أيام حسوماً", "أربعين يوماً", "سنة كاملة", 1,
            "ورد النص الصريح في سورة الحاقة: ﴿سَخَّرَهَا عَلَيْهِمْ سَبْعَ لَيَالٍ وَثَمَانِيَةَ أَيَّامٍ حُسُومًا﴾."),
        q(457L, PROPHETS, HARD, "ما السبب في تسمية المائدة التي أنزلها الله على الحواريين بأنها عيد لأولهم وآخرهم؟",
            "بسبب استجابة دعاء عيسى عليه السلام أن تكون آيةً على صدقه وعيداً يجتمعون على شكر الله فيه", "لأنها كانت من الذهب", "لأنها نزلت في عيد الأضحى", "لأن فرعون صنعها", 0,
            "قال عيسى عليه السلام: ﴿رَبَّنَا أَنزِلْ عَلَيْنَا مَائِدَةً مِّنَ السَّمَاءِ تَكُونُ لَنَا عِيدًا لِّأَوَّلِنَا وَآخِرِنَا وَآيَةً مِّنكَ﴾."),
        q(458L, PROPHETS, HARD, "ما اسم الملك الذي آتاه الله الحكمة وولّاه على بني إسرائيل لقتال جالوت وكانت آية ملكه التابوت؟",
            "داود عليه السلام", "طالوت", "شاول بن غيره", "ذو القرنين", 1,
            "قال تعالى: ﴿إِنَّ اللَّهَ قَدْ بَعَثَ لَكُمْ طَالُوتَ مَلِكًا﴾ وزاده بسطة في العلم والجسم."),
        q(459L, PROPHETS, HARD, "ماذا حدث لقوم «أصحاب السبت» الذين احتالوا على صيد الحيتان يوم السبت المحرم عليهم؟",
            "أُرسل عليهم طوفان", "مسخهم الله قردة خاسئين بعد أن نهتهم طائفة صالحة ولم ينتهوا", "ابتلعتهم الحيتان", "نجوا جميعاً", 1,
            "وردت قصتهم في سورة الأعراف عبرةً لمن يتحايل على محارم الله، بينما أنجى الله الذين ينهون عن السوء."),
        q(460L, PROPHETS, HARD, "كيف استجاب الله لدعاء موسى عليه السلام بإنبات طعام مميز لبني إسرائيل في التيه غير السلوى؟",
            "أخرج لهم من التين والعنب", "أنزل عليهم المن والسلوى، ولما سألوا بقولها وفومها وعدسها وبصلها أنبهم لأنهم يستبدلون الذي هو أدنى بالذي هو خير", "أمرهم بالزراعة في مصر", "بعث لهم القوافل", 1,
            "أنزل الله عليهم المن والسلوى رزقاً طيباً بلا تعب، فلما ضجروا وطلبوا البقل والقثاء والعدس قيل لهم اهبطوا مصراً فإن لكم ما سألتم."),
        q(461L, PROPHETS, HARD, "من هم النبيان المعاصران اللذان أرسلهما الله إلى أهل قرية واحدة ثم عززهما بثالث في مطلع قصة أصحاب القرية بسورة يس؟",
            "هود وصالح ولوط", "رسولان عززا بثالث في قرية (قيل إنطاكية)، وجاء رجل من أقصى المدينة ينصح قومه باتباعهم", "موسى وهارون ويوشع", "زكريا ويحيى وعيسى", 1,
            "تروي سورة يس قصة أصحاب القرية الذين كذبوا المرسلين، ونصيحة المؤمن الذي قتله قومه فأدخله الله الجنة."),
        q(462L, PROPHETS, MEDIUM, "ماذا طلب نبي الله إبراهيم عليه السلام من ربه عند الكعبة ليريه كيف يحيي الموتى ليطمئن قلبه؟",
            "طلب أربعة من الطير يذبحهن ويوزعهن على الجبال ثم يدعوهن فيأتينه سعياً", "طلب شق البحر", "طلب إنزال مائدة", "طلب تحول العصا حية", 0,
            "في سورة البقرة الآية 260، أرى الله إبراهيم عليه السلام قدرته الباهرة على إحياء الموتى بإعادة الطيور إليه سعياً."),
    )
}
